import{_ as i,a0 as m,w as p,s as u,I as e,x as r,a1 as o,A as s,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起 | LCTT x X-CMD","titleTemplate":false,"description":"《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20180116 Command Line Heroes- Season 1- OS Wars_2","title":"《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起","tag":"201909","desc":""},"relativePath":"201909/20180116 Command Line Heroes- Season 1- OS Wars_2.md","filePath":"[post].md"}'),l={name:"201909/20180116 Command Line Heroes- Season 1- OS Wars_2.md"};function g(L,n,x,d,S,b){const t=m("Link");return p(),u("div",null,[n[28]||(n[28]=e("h1",{id:"《代碼英雄》第一季-2-操作系統戰爭-下-linux-崛起",tabindex:"-1"},[r("《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起 "),e("a",{class:"header-anchor",href:"#《代碼英雄》第一季-2-操作系統戰爭-下-linux-崛起","aria-label":"Permalink to “《代碼英雄》第一季（2）：操作系統戰爭（下）Linux 崛起”"},"​")],-1)),n[29]||(n[29]=e("blockquote",null,[e("p",null,"代碼英雄講述了開發人員、程序員、黑客、極客和開源反叛者如何徹底改變技術前景的真實史詩故事。")],-1)),n[30]||(n[30]=e("p",null,[e("img",{src:"https://www.redhat.com/files/webux/img/bandbg/bkgd-clh-ep2-2000x950.png",alt:""})],-1)),e("p",null,[n[3]||(n[3]=r("本文是《",-1)),o(t,{href:"https://www.redhat.com/en/command-line-heroes"},{default:s(()=>[...n[0]||(n[0]=[r("代碼英雄",-1)])]),_:1}),n[4]||(n[4]=r("》系列播客",-1)),o(t,{href:"https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-2-rise-of-linux"},{default:s(()=>[...n[1]||(n[1]=[r("第一季（2）：操作系統戰爭（下）",-1)])]),_:1}),n[5]||(n[5]=r(" 的",-1)),o(t,{href:"https://dts.podtrac.com/redirect.mp3/audio.simplecast.com/2199861a.mp3"},{default:s(()=>[...n[2]||(n[2]=[r("音頻",-1)])]),_:1}),n[6]||(n[6]=r("腳本。",-1))]),n[31]||(n[31]=a("<blockquote><p>微軟帝國控制着 90％ 的用户。操作系統的完全標準化似乎是板上釘釘的事了。但是一個不太可能的英雄出現在開源反叛組織中。戴着眼鏡，温文爾雅的<ruby>林納斯·託瓦茲<rt>Linus Torvalds</rt></ruby>免費發佈了他的 Linux® 程序。微軟打了個趔趄，並且開始重整旗鼓而來，戰場從個人電腦轉向互聯網。</p></blockquote><p><strong>Saron Yitbarek:</strong> 這玩意開着的嗎？讓我們進一段史詩般的星球大戰的開幕吧，開始了。</p><p>配音：第二集：Linux® 的崛起。微軟帝國控制着 90% 的桌面用户。操作系統的全面標準化似乎是板上釘釘的事了。然而，互聯網的出現將戰爭的焦點從桌面轉向了企業，在該領域，所有商業組織都爭相構建自己的服務器。<em>[00:00:30]</em>與此同時，一個不太可能的英雄出現在開源反叛組織中。固執、戴着眼鏡的 <ruby>林納斯·託瓦茲<rt>Linus Torvalds</rt></ruby>免費發佈了他的 Linux 系統。微軟打了個趔趄，並且開始重整旗鼓而來。</p><p><strong>Saron Yitbarek:</strong> 哦，我們書呆子就是喜歡那樣。上一次我們講到哪了？蘋果和微軟互相攻伐，試圖在一場爭奪桌面用户的戰爭中佔據主導地位。<em>[00:01:00]</em> 在第一集的結尾，我們看到微軟獲得了大部分的市場份額。很快，由於互聯網的興起以及隨之而來的開發者大軍，整個市場都經歷了一場地震。互聯網將戰場從在家庭和辦公室中的個人電腦用户轉移到擁有數百台服務器的大型商業客户中。</p><p>這意味着巨量資源的遷移。突然間，所有相關企業不僅被迫為服務器空間和網站建設付費，而且還必須集成軟件來進行資源跟蹤和資料庫監控等工作。<em>[00:01:30]</em> 你需要很多開發人員來幫助你。至少那時候大家都是這麼做的。</p><p>在操作系統之戰的第二部分，我們將看到優先級的巨大轉變，以及像林納斯·託瓦茲和<ruby>理查德·斯托爾曼<rt>Richard Stallman</rt></ruby>這樣的開源反逆者是如何成功地在微軟和整個軟件行業的核心地帶引發恐懼的。</p><p>我是 Saron Yitbarek，你現在收聽的是代碼英雄，一款紅帽公司原創的播客節目。<em>[00:02:00]</em> 每一集，我們都會給你帶來“從碼開始”改變技術的人的故事。</p><p>好。想像一下你是 1991 年時的微軟。你自我感覺良好，對吧？滿懷信心。確立了全球主導的地位感覺不錯。你已經掌握了與其他企業合作的藝術，但是仍然將大部分開發人員、程序員和系統管理員排除在聯盟之外，而他們才是真正的步兵。<em>[00:02:30]</em> 這時出現了個叫林納斯·託瓦茲的芬蘭極客。他和他的開源程序員團隊正在開始發佈 Linux，這個操作系統內核是由他們一起編寫出來的。</p><p>坦白地説，如果你是微軟公司，你並不會太在意 Linux，甚至不太關心開源運動，但是最終，Linux 的規模變得如此之大，以至於微軟不可能不注意到。<em>[00:03:00]</em> Linux 第一個版本出現在 1991 年，當時大概有 1 萬行代碼。十年後，變成了 300 萬行代碼。如果你想知道，今天則是 2000 萬行代碼。</p><p><em>[00:03:30]</em> 讓我們停留在 90 年代初一會兒。那時 Linux 還沒有成為我們現在所知道的龐然大物。這個奇怪的病毒式的操作系統只是正在這個星球上蔓延，全世界的極客和黑客都愛上了它。那時候我還太年輕，但有點希望我曾經經歷過那個時候。在那個時候，發現 Linux 就如同進入了一個秘密社團一樣。就像其他人分享地下音樂混音帶一樣，程序員與朋友們分享 Linux CD 集。</p><p>開發者 Tristram Oaten <em>[00:03:40]</em> 講講你 16 歲時第一次接觸 Linux 的故事吧。</p><p><strong>Tristram Oaten:</strong> 我和我的家人去了紅海的 Hurghada 潛水度假。那是一個美麗的地方，強烈推薦。第一天，我喝了自來水。也許，我媽媽跟我説過不要這麼做。我整個星期都病得很厲害，沒有離開旅館房間。<em>[00:04:00]</em> 當時我只帶了一台新安裝了 Slackware Linux 的筆記本電腦，我聽説過這玩意並且正在嘗試使用它。所有的東西都在 8 張 cd 裏面。這種情況下，我只能整個星期都去了解這個外星一般的系統。我閲讀手冊，擺弄着終端。我記得當時我甚至不知道一個點（表示當前目錄）和兩個點（表示前一個目錄）之間的區別。</p><p><em>[00:04:30]</em> 我一點頭緒都沒有。犯過很多錯誤，但慢慢地，在這種強迫的孤獨中，我突破了障礙，開始理解並明白命令列到底是怎麼回事。假期結束時，我沒有看過金字塔、尼羅河等任何埃及遺址，但我解鎖了現代世界的一個奇蹟。我解鎖了 Linux，接下來的事大家都知道了。</p><p><strong>Saron Yitbarek:</strong> 你會從很多人那裏聽到關於這個故事的不同説法。訪問 Linux 命令列是一種革命性的體驗。</p><p><strong>David Cantrell:</strong> <em>[00:05:00]</em> 它給了我源代碼。我當時的感覺是，“太神奇了。”</p><p><strong>Saron Yitbarek:</strong> 我們正在參加一個名為 Flock to Fedora 的 2017 年 Linux 開發者大會。</p><p><strong>David Cantrell:</strong> ……非常有吸引力。我覺得我對這個系統有了更多的控制力，它越來越吸引我。我想，從 1995 年我第一次編譯 Linux 內核那時起，我就迷上了它。</p><p><strong>Saron Yitbarek:</strong> 開發者 David Cantrell 與 Joe Brockmire。</p><p><strong>Joe Brockmeier:</strong> <em>[00:05:30]</em> 我在 Cheap Software 轉的時候發現了一套四張 CD 的 Slackware Linux。它看起來來非常令人興奮而且很有趣，所以我把它帶回家，安裝在第二台電腦上，開始擺弄它，有兩件事情讓我感到很興奮：一個是，我運行的不是 Windows，另一個是 Linux 的開源特性。</p><p><strong>Saron Yitbarek:</strong> <em>[00:06:00]</em> 某種程度上來説，對命令列的使用總是存在的。在開源真正開始流行還要早的幾十年前，人們（至少在開發人員中是這樣）總是希望能夠做到完全控制。讓我們回到操作系統大戰之前的那個時代，在蘋果和微軟為他們的 GUI 而戰之前。那時也有代碼英雄。<ruby>保羅·瓊斯<rt>Paul Jones</rt></ruby>教授（在線圖書館 ibiblio.org 的負責人）在那個古老的時代，就是一名開發人員。</p><p><strong>Paul Jones:</strong> <em>[00:06:30]</em> 從本質上講，互聯網在那個時候客户端-服務器架構還是比較少的，而更多的是點對點架構的。確實，我們會説，某種 VAX 到 VAX 的連接（LCTT 譯註：DEC 的一種操作系統），某種科學工作站到科學工作站的連接。這並不意味着沒有客户端-服務端的架構及應用程序，但這的確意味着，最初的設計是思考如何實現點對點，<em>[00:07:00]</em> 它與 IBM 一直在做的東西相對立。IBM 給你的只有啞終端，這種終端只能讓你管理用户界面，卻無法讓你像真正的終端一樣為所欲為。</p><p><strong>Saron Yitbarek:</strong> 圖形用户界面在普通用户中普及的同時，在工程師和開發人員中總是存在着一股相反的力量。早在 Linux 出現之前的二十世紀七八十年代，這股力量就存在於 Emacs 和 GNU 中。有了斯托爾曼的自由軟件基金會後，總有某些人想要使用命令列，但上世紀 90 年代的 Linux 提供了前所未有的東西。</p><p><em>[00:07:30]</em> Linux 和其他開源軟件的早期愛好者是都是先驅。我正站在他們的肩膀上。我們都是。</p><p>你現在收聽的是代碼英雄，一款由紅帽公司原創的播客。這是操作系統大戰的第二部分：Linux 崛起。</p><p><strong>Steven Vaughan-Nichols:</strong> 1998 年的時候，情況發生了變化。</p><p><strong>Saron Yitbarek:</strong> <em>[00:08:00]</em> Steven Vaughan-Nichols 是 zdnet.com 的特約編輯，他已經寫了幾十年關於技術商業方面的文章了。他將向我們講述 Linux 是如何慢慢變得越來越流行，直到自願貢獻者的數量遠遠超過了在 Windows 上工作的微軟開發人員的數量的。不過，Linux 從未真正追上微軟桌面客户的數量，這也許就是微軟最開始時忽略了 Linux 及其開發者的原因。Linux 真正大放光彩的地方是在服務器機房。當企業開始線上業務時，每個企業都需要一個滿足其需求的獨特編程解決方案。</p><p><em>[00:08:30]</em> WindowsNT 於 1993 年問世，當時它已經在與其他的服務器操作系統展開競爭了，但是許多開發人員都在想，“既然我可以通過 Apache 構建出基於 Linux 的廉價系統，那我為什麼要購買 AIX 設備或大型 Windows 設備呢？”關鍵點在於，Linux 代碼已經開始滲透到幾乎所有網上的東西中。</p><p><strong>Steven Vaughan-Nichols:</strong> <em>[00:09:00]</em> 令微軟感到驚訝的是，它開始意識到，Linux 實際上已經開始有一些商業應用，不是在桌面環境，而是在商業服務器上。因此，他們發起了一場運動，我們稱之為 FUD - <ruby>恐懼、不確定和懷疑<rt>fear, uncertainty and double</rt></ruby>。他們説，“哦，Linux 這玩意，真的沒有那麼好。它不太可靠。你一點都不能相信它”。</p><p><strong>Saron Yitbarek:</strong> 這種軟宣傳式的攻擊持續了一段時間。微軟也不是唯一一個對 Linux 感到緊張的公司。這其實是整個行業在對抗這個奇怪新人的挑戰。<em>[00:09:30]</em> 例如，任何與 UNIX 有利害關係的人都可能將 Linux 視為篡奪者。有一個案例很著名，那就是 SCO 組織（它發行過一種 UNIX 版本）在過去 10 多年裏發起一系列的訴訟，試圖阻止 Linux 的傳播。SCO 最終失敗而且破產了。與此同時，微軟一直在尋找機會，他們必須要採取動作，只是不清楚具體該怎麼做。</p><p><strong>Steven Vaughan-Nichols:</strong> <em>[00:10:00]</em> 讓微軟真正擔心的是，第二年，在 2000 年的時候，IBM 宣佈，他們將於 2001 年投資 10 億美元在 Linux 上。現在，IBM 已經不再涉足個人電腦業務。（那時）他們還沒有走出去，但他們正朝着這個方向前進，他們將 Linux 視為服務器和大型計算機的未來，在這一點上，劇透警告，IBM 是正確的。<em>[00:10:30]</em> Linux 將主宰服務器世界。</p><p><strong>Saron Yitbarek:</strong> 這已經不再僅僅是一羣黑客喜歡他們對命令列的絕地武士式的控制了。金錢的投入對 Linux 助力極大。<ruby>Linux 國際<rt>Linux International</rt></ruby>的執行董事 John “Mad Dog” Hall 有一個故事可以解釋為什麼會這樣。我們通過電話與他取得了聯繫。</p><p><strong>John Hall:</strong> <em>[00:11:00]</em> 我有一個名叫 Dirk Holden 的朋友，他是德國德意志銀行的系統管理員，他也參與了個人電腦上早期 X Windows 系統圖形項目的工作。有一天我去銀行拜訪他，我説：“Dirk，你銀行裏有 3000 台服務器，用的都是 Linux。為什麼不用 Microsoft NT 呢？”<em>[00:11:30]</em> 他看着我説：“是的，我有 3000 台服務器，如果使用微軟的 Windows NT 系統，我需要 2999 名系統管理員。”他繼續説道：“而使用 Linux，我只需要四個。”這真是完美的答案。</p><p><strong>Saron Yitbarek:</strong> 程序員們着迷的這些東西恰好對大公司也極具吸引力。但由於 FUD 的作用，一些企業對此持謹慎態度。<em>[00:12:00]</em> 他們聽到開源，就想：“開源。這看起來不太可靠，很混亂，充滿了 BUG”。但正如那位銀行經理所指出的，金錢有一種有趣的方式，可以説服人們克服困境。甚至那些只需要網站的小公司也加入了 Linux 陣營。與一些昂貴的專有選擇相比，使用一個廉價的 Linux 系統在成本上是無法比擬的。如果你是一家僱傭專業人員來構建網站的商店，那麼你肯定想讓他們使用 Linux。</p><p>讓我們快進幾年。Linux 運行每個人的網站上。Linux 已經征服了服務器世界，然後智能手機也隨之誕生。<em>[00:12:30]</em> 當然，蘋果和他們的 iPhone 佔據了相當大的市場份額，而且微軟也希望能進入這個市場，但令人驚訝的是，Linux 也在那，已經做好準備了，迫不及待要大展拳腳。</p><p>作家兼記者 James Allworth。</p><p><strong>James Allworth:</strong> 肯定還有容納第二個競爭者的空間，那本可以是微軟，但是實際上卻是 Android，而 Andrid 基本上是基於 Linux 的。眾所周知，Android 被谷歌所收購，現在運行在世界上大部分的智能手機上，谷歌在 Linux 的基礎上創建了 Android。<em>[00:13:00]</em> Linux 使他們能夠以零成本從一個非常複雜的操作系統開始。他們成功地實現了這一目標，最終將微軟擋在了下一代設備之外，至少從操作系統的角度來看是這樣。</p><p><strong>Saron Yitbarek:</strong> <em>[00:13:30]</em> 這可是個大地震，很大程度上，微軟有被埋沒的風險。John Gossman 是微軟 Azure 團隊的首席架構師。他還記得當時困擾公司的困惑。</p><p><strong>John Gossman:</strong> 像許多公司一樣，微軟也非常擔心知識產權污染。他們認為，如果允許開發人員使用開源代碼，那麼他們可能只是將一些代碼複製並粘貼到某些產品中，就會讓某種病毒式的許可證生效從而引發未知的風險……他們也很困惑，<em>[00:14:00]</em> 我認為，這跟公司文化有關，很多公司，包括微軟，都對開源開發的意義和商業模式之間的分歧感到困惑。有一種觀點認為，開源意味着你所有的軟件都是免費的，人們永遠不會付錢。</p><p><strong>Saron Yitbarek:</strong> 任何投資於舊的、專有軟件模型的人都會覺得這裏發生的一切對他們構成了威脅。當你威脅到像微軟這樣的大公司時，是的，他們一定會做出反應。<em>[00:14:30]</em> 他們推動所有這些 FUD —— 恐懼、不確定性和懷疑是有道理的。當時，商業運作的方式基本上就是相互競爭。不過，如果是其他公司的話，他們可能還會一直懷恨在心，抱殘守缺，但到了 2013 年的微軟，一切都變了。</p><p>微軟的雲計算服務 Azure 上線了，令人震驚的是，它從第一天開始就提供了 Linux 虛擬機。<em>[00:15:00]</em> <ruby>史蒂夫·鮑爾默<rt>Steve Ballmer</rt></ruby>，這位把 Linux 稱為癌症的首席執行官，已經離開了，代替他的是一位新的有遠見的首席執行官<ruby>薩提亞·納德拉<rt>Satya Nadella</rt></ruby>。</p><p><strong>John Gossman:</strong> 薩提亞有不同的看法。他屬於另一個世代。比保羅、比爾和史蒂夫更年輕的世代，他對開源有不同的看法。</p><p><strong>Saron Yitbarek:</strong> 還是來自微軟 Azure 團隊的 John Gossman。</p><p><strong>John Gossman:</strong> <em>[00:15:30]</em> 大約四年前，處於實際需要，我們在 Azure 中添加了 Linux 支持。如果訪問任何一家企業客户，你都會發現他們並不會才試着決定是使用 Windows 還是使用 Linux、 使用 .net 還是使用 Java ^TM 。他們在很久以前就做出了決定 —— 大約 15 年前才有這樣的一些爭論。<em>[00:16:00]</em> 現在，我見過的每一家公司都混合了 Linux 和 Java、Windows 和 .net、SQL Server、Oracle 和 MySQL —— 基於專有源代碼的產品和開放源代碼的產品。</p><p>如果你打算運維一個雲服務，允許這些公司在雲上運行他們的業務，那麼你根本不能告訴他們，“你可以使用這個軟件，但你不能使用那個軟件。”</p><p><strong>Saron Yitbarek:</strong> <em>[00:16:30]</em> 這正是薩提亞·納德拉採納的哲學思想。2014 年秋季，他站在舞台上，希望傳遞一個重要信息。“微軟愛 Linux”。他接着説，“20% 的 Azure 業務量已經是 Linux 了，微軟將始終對 Linux 發行版提供一流的支持。”沒有哪怕一絲對開源的宿怨。</p><p>為了説明這一點，在他們的背後有一個巨大的標誌，上面寫着：“Microsoft ❤️ Linux”。哇噢。對我們中的一些人來説，這種轉變有點令人震驚，但實際上，無需如此震驚。下面是 Steven Levy，一名科技記者兼作家。</p><p><strong>Steven Levy:</strong> <em>[00:17:00]</em> 當你在踢足球的時候，如果草坪變滑了，那麼你也許會換一種不同的鞋子。他們當初就是這麼做的。<em>[00:17:30]</em> 他們不能否認現實，而且他們裏面也有聰明人，所以他們必須意識到，這就是這個世界的運行方式，不管他們早些時候説了什麼，即使他們對之前的言論感到尷尬，但是讓他們之前關於開源多麼可怕的言論影響到現在明智的決策那才真的是瘋了。</p><p><strong>Saron Yitbarek:</strong> 微軟低下了它高傲的頭。你可能還記得蘋果公司，經過多年的孤立無援，最終轉向與微軟構建合作伙伴關係。現在輪到微軟進行 180 度轉變了。<em>[00:18:00]</em> 經過多年的與開源方式的戰鬥後，他們正在重塑自己。要麼改變，要麼死亡。Steven Vaughan-Nichols。</p><p><strong>Steven Vaughan-Nichols:</strong> 即使是像微軟這樣規模的公司也無法與數千個開發着包括 Linux 在內的其它大項目的開源開發者競爭。很長時間以來他們都不願意這麼做。前微軟首席執行官史蒂夫·鮑爾默對 Linux 深惡痛絕。<em>[00:18:30]</em> 由於它的 GPL 許可證，他視 Linux 為一種癌症，但一旦鮑爾默被掃地出門，新的微軟領導層説，“這就好像試圖命令潮流不要過來，但潮水依然會不斷湧進來。我們應該與 Linux 合作，而不是與之對抗。”</p><p><strong>Saron Tiebreak:</strong> 事實上，互聯網技術史上最大的勝利之一就是微軟最終決定做出這樣的轉變。<em>[00:19:00]</em> 當然，當微軟出現在開源圈子時，老一代的鐵桿 Linux 支持者是相當懷疑的。他們不確定自己是否能接受這些傢伙，但正如 Vaughan-Nichols 所指出的，今天的微軟已經不是以前的微軟了。</p><p><strong>Steven Vaughan-Nichols:</strong> 2017 年的微軟既不是史蒂夫·鮑爾默的微軟，也不是比爾·蓋茨的微軟。這是一家完全不同的公司，有着完全不同的方法，而且，一旦使用了開源，你就無法退回到之前。<em>[00:19:30]</em> 開源已經吞噬了整個技術世界。從未聽説過 Linux 的人可能對它並不瞭解，但是每次他們訪問 Facebook，他們都在運行 Linux。每次執行谷歌搜索時，你都在運行 Linux。</p><p><em>[00:20:00]</em> 每次你用 Android 手機，你都在運行 Linux。它確實無處不在，微軟無法阻止它，而且我認為以為微軟能以某種方式接管它的想法，太天真了。</p><p><strong>Saron Yitbarek:</strong> 開源支持者可能一直擔心微軟會像混入羊羣中的狼一樣，但事實是，開源軟件的本質保護了它無法被完全控制。<em>[00:20:30]</em> 沒有一家公司能夠擁有 Linux 並以某種特定的方式控制它。Greg Kroah-Hartman 是 Linux 基金會的一名成員。</p><p><strong>Greg Kroah-Hartman:</strong> 每個公司和個人都以自私的方式為 Linux 做出貢獻。他們之所以這樣做是因為他們想要解決他們所面臨的問題，可能是硬件無法工作，或者是他們想要添加一個新功能來做其他事情，又或者想在他們的產品中使用它。這很棒，因為他們會把代碼貢獻回去，此後每個人都會從中受益，這樣每個人都可以用到這份代碼。正是因為這種自私，所有的公司，所有的人都能從中受益。</p><p><strong>Saron Yitbarek:</strong> <em>[00:21:00]</em> 微軟已經意識到，在即將到來的雲戰爭中，與 Linux 作戰就像與空氣作戰一樣。Linux 和開源不是敵人，它們是空氣。如今，微軟以白金會員的身份加入了 Linux 基金會。他們成為 GitHub 開源項目的頭號貢獻者。<em>[00:21:30]</em> 2017 年 9 月，他們甚至加入了<ruby>開源促進聯盟<rt>Open Source Initiative</rt></ruby>。現在，微軟在開源許可證下發布了很多代碼。微軟的 John Gossman 描述了他們開源 .net 時所發生的事情。起初，他們並不認為自己能得到什麼回報。</p><p><strong>John Gossman:</strong> 我們本沒有指望來自社區的貢獻，然而，三年後，超過 50% 的對 .net 框架庫的貢獻來自於微軟之外。這包括大量的代碼。<em>[00:22:00]</em> 三星為 .net 提供了 ARM 支持。Intel 和 ARM 以及其他一些芯片廠商已經為 .net 框架貢獻了特定於他們處理器的代碼生成，以及數量驚人的修復、性能改進等等 —— 既有單個貢獻者也有社區。</p><p><strong>Saron Yitbarek:</strong> 直到幾年前，今天的這個微軟，這個開放的微軟，還是不可想像的。</p><p><em>[00:22:30]</em> 我是 Saron Yitbarek，這裏是代碼英雄。好吧，我們已經看到了為了贏得數百萬桌面用户的愛而戰的激烈場面。我們已經看到開源軟件在專有軟件巨頭的背後悄然崛起，並攫取了巨大的市場份額。<em>[00:23:00]</em> 我們已經看到了一批批的代碼英雄將編程領域變成了我你今天看到的這個樣子。如今，大企業正在吸收開源軟件，通過這一切，每個人都從他人那裏受益。</p><p>在技術的西部荒野，一貫如此。蘋果受到施樂的啓發，微軟受到蘋果的啓發，Linux 受到 UNIX 的啓發。進化、借鑑、不斷成長。如果比喻成大衞和歌利亞（LCTT 譯註：西方經典的以弱勝強戰爭中的兩個主角）的話，開源軟件不再是大衞，但是，你知道嗎？它也不是歌利亞。<em>[00:23:30]</em> 開源已經超越了傳統。它已經成為其他人戰鬥的戰場。隨着開源道路變得不可避免，新的戰爭，那些在雲計算中進行的戰爭，那些在開源戰場上進行的戰爭正在加劇。</p><p>這是 Steven Levy，他是一名作者。</p><p><strong>Steven Levy:</strong> 基本上，到目前為止，包括微軟在內，有四到五家公司，正以各種方式努力把自己打造成為全方位的平台，比如人工智能領域。你能看到智能助手之間的戰爭，你猜怎麼着？<em>[00:24:00]</em> 蘋果有一個智能助手，叫 Siri。微軟有一個，叫 Cortana。谷歌有谷歌助手。三星也有一個智能助手。亞馬遜也有一個，叫 Alexa。我們看到這些戰鬥遍佈各地。也許，你可以説，最熱門的人工智能平台將控制我們生活中所有的東西，而這五家公司就是在為此而爭鬥。</p><p><strong>Saron Yitbarek:</strong> <em>[00:24:30]</em> 如果你正在尋找另一個反叛者，它們就像 Linux 奇襲微軟那樣，偷偷躲在 Facebook、谷歌或亞馬遜身後，你也許要等很久，因為正如作家 James Allworth 所指出的，成為一個真正的反叛者只會變得越來越難。</p><p><strong>James Allworth:</strong> 規模一直以來都是一種優勢，但規模優勢本質上……怎麼説呢，我認為以前它們在本質上是線性的，現在它們在本質上是指數型的了，所以，一旦你開始以某種方法走在前面，另一個新玩家要想趕上來就變得越來越難了。<em>[00:25:00]</em> 我認為在互聯網時代這大體來説來説是正確的，無論是因為規模，還是數據賦予組織的競爭力的重要性和優勢。一旦你走在前面，你就會吸引更多的客户，這就給了你更多的數據，讓你能做得更好，這之後，客户還有什麼理由選擇排名第二的公司呢，難道是因為因為他們落後了這麼遠麼？<em>[00:25:30]</em> 我認為在雲的時代這個邏輯也不會有什麼不同。</p><p><strong>Saron Yitbarek:</strong> 這個故事始於史蒂夫·喬布斯和比爾·蓋茨這樣的非凡的英雄，但科技的進步已經呈現出一種眾包、有機的感覺。我認為據説我們的開源英雄林納斯·託瓦茲在第一次發明 Linux 內核時甚至沒有一個真正的計劃。他無疑是一位才華橫溢的年輕開發者，但他也像潮汐前的一滴水一樣。<em>[00:26:00]</em> 變革是不可避免的。據估計，對於一家專有軟件公司來説，用他們老式的、專有的方式創建一個 Linux 發行版將花費他們超過 100 億美元。這説明了開源的力量。</p><p>最後，這並不是一個專有模型所能與之競爭的東西。成功的公司必須保持開放。這是最大、最終極的教訓。<em>[00:26:30]</em> 還有一點要記住：當我們連接在一起的時候，我們在已有基礎上成長和建設的能力是無限的。不管這些公司有多大，我們都不必坐等他們給我們更好的東西。想想那些為了純粹的創造樂趣而學習編碼的新開發者，那些自己動手豐衣足食的人。</p><p>未來的優秀程序員無管來自何方，只要能夠訪問代碼，他們就能構建下一個大項目。</p>",66)),e("p",null,[n[8]||(n[8]=e("em",null,"[00:27:00]",-1)),n[9]||(n[9]=r(" 以上就是我們關於操作系統戰爭的兩個故事。這場戰爭塑造了我們的數字生活。爭奪主導地位的鬥爭從桌面轉移到了服務器機房，最終進入了雲計算領域。過去的敵人難以置信地變成了盟友，眾包的未來讓一切都變得開放。",-1)),n[10]||(n[10]=e("em",null,"[00:27:30]",-1)),n[11]||(n[11]=r(" 聽着，我知道，在這段歷史之旅中，還有很多英雄我們沒有提到，所以給我們寫信吧。分享你的故事。",-1)),o(t,{href:"https://www.redhat.com/commandlineheroes"},{default:s(()=>[...n[7]||(n[7]=[r("Redhat.com/commandlineheroes",-1)])]),_:1}),n[12]||(n[12]=r(" 。我恭候佳音。",-1))]),n[32]||(n[32]=e("p",null,"在本季剩下的時間裏，我們將學習今天的英雄們在創造什麼，以及他們要經歷什麼樣的戰鬥才能將他們的創造變為現實。讓我們從壯麗的編程一線回來看看更多的傳奇故事吧。我們每兩週放一集新的Blog。幾周後，我們將為你帶來第三集：敏捷革命。",-1)),n[33]||(n[33]=e("p",null,[e("em",null,"[00:28:00]"),r(" 代碼英雄是一款紅帽公司原創的播客。要想免費自動獲得新一集的代碼英雄，請訂閲我們的節目。只要在蘋果播客、Spotify、谷歌 Play，或其他應用中搜索“Command Line Heroes”。然後點擊“訂閲”。這樣你就會第一個知道什麼時候有新劇集了。")],-1)),n[34]||(n[34]=e("p",null,"我是 Saron Yitbarek。感謝收聽。繼續編碼。",-1)),n[35]||(n[35]=e("hr",null,null,-1)),e("p",null,[n[14]||(n[14]=r("via: ",-1)),o(t,{href:"https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-2-rise-of-linux"},{default:s(()=>[...n[13]||(n[13]=[r("https://www.redhat.com/en/command-line-heroes/season-1/os-wars-part-2-rise-of-linux",-1)])]),_:1})]),e("p",null,[n[19]||(n[19]=r("作者：",-1)),o(t,{href:"https://www.redhat.com"},{default:s(()=>[...n[15]||(n[15]=[r("redhat",-1)])]),_:1}),n[20]||(n[20]=r(" 選題：",-1)),o(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...n[16]||(n[16]=[r("lujun9972",-1)])]),_:1}),n[21]||(n[21]=r(" 譯者：",-1)),o(t,{href:"https://github.com/lujun9972"},{default:s(()=>[...n[17]||(n[17]=[r("lujun9972",-1)])]),_:1}),n[22]||(n[22]=r(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:s(()=>[...n[18]||(n[18]=[r("wxy",-1)])]),_:1})]),e("p",null,[n[25]||(n[25]=r("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...n[23]||(n[23]=[r("LCTT",-1)])]),_:1}),n[26]||(n[26]=r(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:s(()=>[...n[24]||(n[24]=[r("Linux中國",-1)])]),_:1}),n[27]||(n[27]=r(" 榮譽推出",-1))])])}const T=i(l,[["render",g]]);export{f as __pageData,T as default};
